        }

        if ($apiResult instanceof \OpenAPI\Server\Model\PinterestLibError) {
            return response()->json($this->serde->serialize($apiResult, format: 'array'), 429);
        }

        if ($apiResult instanceof \OpenAPI\Server\Model\PinterestLibError) {
